def data(self, *keys):
        """Return the keys and values of this record as a dictionary, optionally including only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        result = {}
        if keys:
            for i, key in enumerate(keys):
                try:
                    value = self[key]
                except KeyError:
                    value = None
                result[key] = value
        else:
            for key, value in self.items():
                result[key] = value
        return result

