def round_half_to_even(n):
    """
    Round a number to the nearest integer. If the number is exactly halfway between two integers,
    round it to the nearest even integer.

    :param n: The number to round.
    :return: The rounded integer.
    """
    if n % 2 == 0:
        return int(n)
    else:
        return int(n + 1)

