def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    if not all(isinstance(field, str) for field in fields):
        raise TypeError("all fields must be strings")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    if not all(isinstance(key, int) for key in srid_map.keys()):
        raise TypeError("all keys in srid_map must be integers")
    if not all(isinstance(value, str) for value in srid_map.values()):
        raise TypeError("all values in srid_map must be strings")

    class PointSubclass(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            for field in fields:
                setattr(self, field, None)

        def __str__(self):
            return ", ".join(str(getattr(self, field)) for field in fields)

        def __repr__(self):
            return f"{name}({', '.join(str(getattr(self, field)) for field in fields)})"

        def __eq__(self, other):
            return all(getattr(self, field) == getattr(other, field) for field in fields)

        def __ne__(self, other):
            return not self == other

        def __hash__(self):
            return hash(tuple(getattr(self, field) for field in fields))

    return PointSubclass

