def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Args:
        cache (dict): A cache to store the results.
        key (function, optional): A function that takes the function arguments
            and returns a hashable key for the cache. Defaults to hashkey.
        lock (threading.Lock, optional): A lock to prevent concurrent access
            to the cache. Defaults to None.

    Returns:
        Callable: A memoizing callable that wraps the original function.
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                key_ = key(*args, **kwargs)
                if key_ in cache:
                    return cache[key_]
                else:
                    value = func(*args, **kwargs)
                    cache[key_] = value
                    return value
            finally:
                if lock is not None:
                    lock.release()
        return wrapper

    return decorator

