def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    Raises:
        TypeError: if the function signature has type annotations and
            `typed` is False.
        ValueError: if `maxsize` is negative.

    """
    if typed and type(maxsize) is not int:
        raise TypeError(f"`maxsize` must be an int, got {type(maxsize)}")
    if maxsize < 0:
        raise ValueError(f"`maxsize` must be non-negative, got {maxsize}")

    cache = {}
    cache_order = []

    def wrapper(*args, **kwargs):
        nonlocal cache, cache_order
        if typed:
            key = (args, tuple(kwargs.items()))
        else:
            key = args + tuple(kwargs.values())
        if key in cache:
            cache_order.remove(key)
            cache_order.append(key)
            return cache[key]
        else:
            result = cache[key] = function(*args, **kwargs)
            cache_order.append(key)
            if len(cache) > maxsize:
                cache.pop(cache_order[0])
                cache_order.pop(0)
            return result

    return wrapper

