def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    try:
        # Check if fixity is a list
        if not isinstance(fixity, list):
            raise ValueError("Fixity must be a list.")

        # Check if each item in the list is a dictionary
        for item in fixity:
            if not isinstance(item, dict):
                raise ValueError("Each item in the fixity list must be a dictionary.")

            # Check if the item has the required keys
            if "filepath" not in item:
                raise KeyError("The 'filepath' key is missing.")
            if "checksum" not in item:
                raise KeyError("The 'checksum' key is missing.")

            # Check if the filepath is valid
            filepath = item["filepath"]
            if filepath not in manifest_files:
                raise ValueError(f"The filepath '{filepath}' is not valid.")

            # Check if the checksum is valid
            checksum = item["checksum"]
            if not isinstance(checksum, str):
                raise ValueError("The checksum must be a string.")
            if not checksum.isalnum():
                raise ValueError("The checksum must be a valid checksum string.")

        return True
    except Exception as e:
        return False

