def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for obj in self.objects.values():
        num_objects += 1
        if validate_objects:
            if not obj.validate():
                if show_warnings:
                    print(f"Object {obj.id} is invalid.")
                continue
        if check_digests:
            if not obj.digest:
                if show_warnings:
                    print(f"Object {obj.id} has no digest.")
                continue
            if not obj.validate_digest():
                if show_warnings:
                    print(f"Object {obj.id} has an invalid digest.")
                continue
        good_objects += 1
    return num_objects, good_objects

