    parsed_arguments = {}
    remaining_arguments = []

    # Try each subparser in order
    for subparser_name, subparser in subparsers.items():
        # Parse the arguments using each subparser
        try:
            parsed_args = subparser.parse_args(unparsed_arguments)
        except ValueError:
            # If the subparser raises a ValueError, it means it didn't match the arguments
            continue

        # Add the parsed arguments to the dict
        parsed_arguments[subparser_name] = parsed_args

        # Remove the parsed arguments from the list of remaining arguments
        for arg in parsed_args._get_args():
            if arg in unparsed_arguments:
                unparsed_arguments.remove(arg)

    # Return the parsed arguments and the remaining arguments
    return parsed_arguments, unparsed_arguments

