def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string or not alphabet:
        raise ValueError("Both the string and alphabet must be provided")

    base = len(alphabet)
    number = 0
    for i, char in enumerate(string):
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"The character {char} is not in the alphabet")

        number += base ** i * digit

    return number

