def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from xml.dom import minidom
    except ImportError:
        from xml.etree import ElementTree
    try:
        from Crypto.Hash import SHA256
    except ImportError:
        from hashlib import sha256
    try:
        from Crypto.PublicKey import RSA
    except ImportError:
        from Cryptodome.PublicKey import RSA
    try:
        from Crypto.Signature import PKCS1_v1_5
    except ImportError:
        from Cryptodome.Signature import PKCS1_v1_5

    # Convert the public key to a RSA key object
    try:
        rsa_key = RSA.import_key(public_key)
    except ValueError:
        raise ValueError("Invalid public key")

    # Generate a SHA-256 hash of the XML document
    xml_doc = minidom.parseString(doc)
    xml_doc.normalize()
    xml_str = xml_doc.toprettyxml()
    xml_hash = SHA256.new(xml_str.encode("utf-8"))

    # Verify the digital signature
    signer = PKCS1_v1_5.new(rsa_key)
    digest = signer.verify(xml_hash, signature)

    # Check if the signature is valid
    if not digest:
        return False

    # Check if the signer's public key matches the public key we have
    if not rsa_key.compare_digest(digest):
        return False

    return True

